// ==============================================================================

window.JUSTIFICATIONS_EMBRYOLOGIE = {
  "embryo-1": {
    "A": "Faux (corrigé officiel). La capacitation des spermatozoïdes se déroule avant la fécondation dans les voies génitales féminines.",
    "B": "Vrai (corrigé officiel). La première semaine du développement embryonnaire est définie par la segmentation (clivage mitotique de l'œuf fécondé en blastomères puis en morula et blastocyste).",
    "C": "Faux (corrigé officiel). La différenciation du trophoblaste en syncytiotrophoblaste et cytotrophoblaste a lieu au début de la 2ème semaine (J8).",
    "D": "Faux (corrigé officiel). La gastrulation correspond à la mise en place du troisième feuillet embryonnaire au cours de la 3ème semaine.",
    "_synthese": "Corrigé officiel de la Faculté de Médecine de Mostaganem : B. Les événements cardinaux de la 1ère semaine sont la fécondation, la segmentation, la formation du blastocyste et l'initiation de la nidation à J6. (Chapitre : La 1ère semaine de développement embryonnaire).",
    "_remarque": "Astuce concours / EMD : Retenez la règle chronologique : S1 = segmentation/blastocyste ; S2 = didermique/implantation ; S3 = tridermique/gastrulation."
  },
  "embryo-2": {
    "A": "Faux (corrigé officiel). Le stade à deux blastomères s'observe au début de la segmentation (environ 24 à 30h post-fécondation), bien avant le stade blastocyste qui compte plus de 64 à 128 cellules.",
    "B": "Faux (corrigé officiel). Le syncytiotrophoblaste n'apparaît qu'au 8ème jour (2ème semaine) par différenciation du trophoblaste.",
    "C": "Vrai (corrigé officiel). Le blastocyste (J5-J6) est constitué d'une masse cellulaire interne (l'embryoblaste ou bouton embryonnaire), d'une couche périphérique (le trophoblaste) et d'une cavité liquidienne centrale (le blastocèle).",
    "D": "Faux (corrigé officiel). Blastokyste est une orthographe désuète et incorrecte désignant l'ensemble de la structure.",
    "_synthese": "Corrigé officiel de la Faculté de Médecine de Mostaganem : C. L'embryoblaste (masse cellulaire interne) donnera tous les tissus du futur fœtus, tandis que le trophoblaste donnera les annexes fœtales et le placenta. (Chapitre : La 1ère semaine de développement embryonnaire).",
    "_remarque": "Astuce concours / EMD : Blastocyste = Embryoblaste (masse cellulaire interne) + Trophoblaste + Blastocèle."
  },
  "embryo-3": {
    "A": "Faux (corrigé officiel). La localisation isthmique représente environ 12 % des grossesses extra-utérines.",
    "B": "Faux (corrigé officiel). Le segment interstitiel (cornual) est rare (2 à 3 %) mais particulièrement dangereux en raison du risque de rupture cataclysmique.",
    "C": "Vrai (corrigé officiel). L'ampoule tubaire est le siège le plus fréquent des grossesses extra-utérines (70 à 80 % des cas), car c'est le lieu physiologique de la fécondation où le retard de captation ou de transit tubaire est maximal.",
    "D": "Faux (corrigé officiel). La grossesse abdominale péritonéale ou mésentérique est exceptionnelle (< 1 %).",
    "_synthese": "Corrigé officiel de la Faculté de Médecine de Mostaganem : C. La GEU ampullaire est la forme clinique et anatomique prédominante des implantations ectopiques. (Chapitre : La 1ère semaine de développement embryonnaire).",
    "_remarque": "Astuce concours / EMD : Ampoule tubaire = 1er lieu de fécondation ET siège de 70-80% des grossesses extra-utérines."
  },
  "embryo-4": {
    "A": "Proposition fausse à cocher (corrigé officiel). La membrane de Slavjanski est la membrane basale folliculaire située entre la granulosa et la thèque interne dans l'ovaire; elle ne fait absolument pas partie de l'embryon.",
    "B": "Proposition vraie (non retenue). La rupture de la zone pellucide est obligatoire pour libérer le blastocyste.",
    "C": "Proposition vraie (non retenue). L'éclosion du blastocyste hors de sa coque glycoprotéique est le prérequis direct de l'adhésion trophoblastique.",
    "D": "Proposition vraie (non retenue). La destruction enzymatique de la membrane basale de l'épithélium endométrial permet l'enfouissement de l'œuf dans le stroma maternel.",
    "_synthese": "Corrigé officiel de la Faculté de Médecine de Mostaganem : A. L'éclosion du blastocyste correspond à l'extrusion de l'embryon hors de la zone pellucide avant la fixation à l'endomètre. (Chapitre : La 1ère semaine de développement embryonnaire).",
    "_remarque": "Astuce concours / EMD : Membrane de Slavjanski = ovaire (folliculogenèse), aucun lien avec l'embryon."
  },
  "embryo-5": {
    "A": "Faux (corrigé officiel). Les globules polaires dégénèrent rapidement après la fécondation dans l'espace périvitellin.",
    "B": "Faux (corrigé officiel). La membrane plasmique des blastomères est interne et protégée par la zone pellucide.",
    "C": "Vrai (corrigé officiel). La zone pellucide, coque glycoprotéique acellulaire épaisse entourant l'œuf fécondé, empêche l'adhésion prématurée du trophoblaste à la paroi tubaire, prévenant ainsi les implantations ectopiques jusqu'à l'éclosion dans la cavité utérine.",
    "D": "Faux (corrigé officiel). La masse cellulaire interne est située à l'intérieur du blastocèle.",
    "_synthese": "Corrigé officiel de la Faculté de Médecine de Mostaganem : C. La zone pellucide joue un rôle de bouclier mécanique et immunologique empêchant la nidation tubaire ectopique. (Chapitre : La 1ère semaine de développement embryonnaire).",
    "_remarque": "Astuce concours / EMD : Tant que la zone pellucide persiste, l'œuf ne peut pas s'implanter."
  },
  "embryo-6": {
    "A": "Faux (corrigé officiel). Le cytotrophoblaste est la couche germinative interne mononucléée qui alimente le syncytiotrophoblaste par divisions mitotiques.",
    "B": "Faux (corrigé officiel). La masse cellulaire interne (embryoblaste) ne participe pas à l'invasion tissulaire endométriale.",
    "C": "Vrai (corrigé officiel). Le syncytiotrophoblaste est une nappe multinucléée hautement invasive qui sécrète des enzymes lytiques (métalloprotéinases, collagénases) érodant l'épithélium et le stroma de l'endomètre pour enfouir le blastocyste.",
    "D": "Faux (corrigé officiel). L'ectoderme n'est pas encore individualisé à ce stade précoce.",
    "_synthese": "Corrigé officiel de la Faculté de Médecine de Mostaganem : C. Le syncytiotrophoblaste possède une activité protéolytique, migratoire et phagocytaire permettant l'implantation invasive interstitielle. (Chapitre : La 2ème semaine de développement embryonnaire).",
    "_remarque": "Astuce concours / EMD : Invasion endométriale + érosion vasculaire + sécrétion d'hCG = Syncytiotrophoblaste."
  },
  "embryo-7": {
    "A": "Faux (corrigé officiel). Au 17ème jour, l'embryon est déjà en pleine gastrulation (3ème semaine).",
    "B": "Faux (corrigé officiel). Au 3ème jour, l'œuf est au stade morula et transite dans la lumière de la trompe de Fallope.",
    "C": "Vrai (corrigé officiel). L'œuf sous forme de blastocyste libre arrive dans la cavité utérine vers le 5e-6e jour après la fécondation (le corrigé officiel retient le 6ème jour), date marquant le début de l'implantation.",
    "D": "Faux (corrigé officiel). Au 21ème jour, la circulation fœto-placentaire débute et la ligne primitive régresse.",
    "_synthese": "Corrigé officiel de la Faculté de Médecine de Mostaganem : C. Le transit tubaire dure environ 3 à 4 jours; l'œuf séjourne librement dans la cavité utérine vers J5-J6 avant de s'implanter. (Chapitre : La 1ère semaine de développement embryonnaire).",
    "_remarque": "Astuce concours / EMD : Arrivée dans la cavité utérine = J5-J6 (stade blastocyste dénudé de sa zone pellucide)."
  },
  "embryo-8": {
    "A": "Faux (corrigé officiel). La segmentation débute dès le premier jour après la fécondation et s'achève au 5e-6e jour.",
    "B": "Faux (corrigé officiel). La segmentation concerne le zygote (l'œuf fécondé) et non l'ovocyte.",
    "C": "Vrai (corrigé officiel). La segmentation se déroule pendant que l'œuf fécondé migre le long de la trompe de Fallope vers la cavité utérine grâce aux contractions musculaires tubaires et aux mouvements des cils vibratiles.",
    "D": "Faux (corrigé officiel). La proposition C est exacte.",
    "_synthese": "Corrigé officiel de la Faculté de Médecine de Mostaganem : C. La segmentation et la migration tubaire sont deux phénomènes strictement concomitants au cours de la première semaine. (Chapitre : La 1ère semaine de développement embryonnaire).",
    "_remarque": "Astuce concours / EMD : La segmentation est un voyage mitotique de la trompe vers l'utérus."
  },
  "embryo-9": {
    "A": "Vrai (corrigé officiel). La réaction acrosomique (exocytose des enzymes acrosomiales comme la hyaluronidase et l'acrosine) ne peut se déclencher qu'après la capacitation préalable du spermatozoïde dans les voies génitales féminines.",
    "B": "Faux (corrigé officiel). Elle se produit au contact de la zone pellucide de l'ovocyte dans l'ampoule tubaire.",
    "C": "Faux (corrigé officiel). La formation de l'acrosome a lieu durant la spermiogenèse dans le testicule (et non lors de la réaction acrosomique).",
    "D": "Faux (corrigé officiel). La proposition A est exacte.",
    "_synthese": "Corrigé officiel de la Faculté de Médecine de Mostaganem : A. La capacitation déstabilise la membrane plasmique du spermatozoïde en éliminant son cholestérol, autorisant l'amorce de la réaction acrosomique au contact de ZP3. (Chapitre : La fécondation).",
    "_remarque": "Astuce concours / EMD : Capacitation (voies génitales féminines) obligatoire AVANT réaction acrosomique (contact ovocytaire)."
  },
  "embryo-10": {
    "A": "Faux (corrigé officiel). Nausées et vomissements sont des signes cliniques sympathiques d'orientation, inconstants et non spécifiques.",
    "B": "Vrai (corrigé officiel). Le dosage quantitatif des fractions bêta de l'hCG (human Chorionic Gonadotropin) plasmatique est le test biologique précoce et spécifique attestant de la présence de tissu trophoblastique fonctionnel et signant la grossesse.",
    "C": "Faux (corrigé officiel). L'aménorrhée est un signe clinique d'appel qui peut avoir de multiples étiologies non gravidiques.",
    "D": "Faux (corrigé officiel). La proposition B est exacte.",
    "_synthese": "Corrigé officiel de la Faculté de Médecine de Mostaganem : B. L'élévation de l'hCG est le premier signe biologique positif de certitude chez la femme enceinte. (Chapitre : La 2ème semaine de développement embryonnaire).",
    "_remarque": "Astuce concours / EMD : Signe précoce de certitude de grossesse = élévation de l'hCG plasmatique."
  },
  "embryo-11": {
    "A": "Vrai (corrigé officiel). La zone pellucide subit une lyse enzymatique (action de la strypsine) lors de la migration et de l'arrivée de l'œuf dans la cavité utérine vers J5-J6 (phénomène d'éclosion).",
    "B": "Faux (corrigé officiel). Elle persiste intacte lors de l'ovulation et entoure l'ovocyte II.",
    "C": "Faux (corrigé officiel). Pendant la fécondation, elle est traversée par un seul spermatozoïde puis subit la réaction corticale pour bloquer la polyspermie, mais elle n'est pas détruite.",
    "D": "Faux (corrigé officiel). Au début de la 3ème semaine, elle a disparu depuis longtemps.",
    "_synthese": "Corrigé officiel de la Faculté de Médecine de Mostaganem : A. L'éclosion correspond à l'ouverture et à la résorption de la zone pellucide dans la lumière utérine. (Chapitre : La 1ère semaine de développement embryonnaire).",
    "_remarque": "Astuce concours / EMD : Destruction de la zone pellucide = Éclosion dans la cavité utérine à J5-J6."
  },
  "embryo-12": {
    "A": "Faux (corrigé officiel). Le stade morula correspond au 3ème et 4ème jour (16 à 32 blastomères).",
    "B": "Faux (corrigé officiel). Le cytotrophoblaste proprement individualisé apparaît à J8.",
    "C": "Vrai (corrigé officiel). A 6 jours, l'œuf est un blastocyste mature constitué du bouton embryonnaire (embryoblaste) et du trophoblaste entourant le blastocèle.",
    "D": "Faux (corrigé officiel). Le syncytiotrophoblaste se différencie au 8ème jour de développement.",
    "_synthese": "Corrigé officiel de la Faculté de Médecine de Mostaganem : C. A J6, l'œuf est un blastocyste dont le bouton embryonnaire donnera le corps de l'embryon. (Chapitre : La 1ère semaine de développement embryonnaire).",
    "_remarque": "Astuce concours / EMD : Œuf de 6 jours = Blastocyste avec Bouton embryonnaire + Trophoblaste + Blastocèle."
  },
  "embryo-13": {
    "A": "Vrai (corrigé officiel). La glaire cervicale est sécrétée par les glandes de la muqueuse du col utérin (endocol) sous dépendance des œstrogènes.",
    "B": "Faux (corrigé officiel). La muqueuse vaginale ne contient pas de glandes sécrétoires propres (elle est lubrifiée par transsudation et glaire cervicale).",
    "C": "Faux (corrigé officiel). La trompe sécrète le fluide tubaire et non la glaire cervicale.",
    "D": "Faux (corrigé officiel). L'ovaire produit les gamètes et les hormones stéroïdiennes.",
    "_synthese": "Corrigé officiel de la Faculté de Médecine de Mostaganem : A. La glaire cervicale filtre les spermatozoïdes anormaux, assure leur capacitation et facilite leur ascension en période péri-ovulatoire. (Chapitre : L'appareil génital féminin).",
    "_remarque": "Astuce concours / EMD : Glaire cervicale = sécrétée par les cryptes du col utérin (endocol)."
  },
  "embryo-14": {
    "A": "Faux (corrigé officiel). Calcul chronologique : dans un cycle régulier de 34 jours, la phase lutéale est fixe de 14 jours, l'ovulation a lieu au 20ème jour (34 - 14 = 20). Le 10ème jour est bien trop précoce.",
    "B": "Faux (corrigé officiel). Le 14ème jour correspondrait à l'ovulation d'un cycle classique de 28 jours, pas d'un cycle de 34 jours.",
    "C": "Faux (corrigé officiel). Au 16ème jour, l'ovulation n'a pas encore eu lieu.",
    "D": "Vrai (corrigé officiel). Calcul : Ovulation = 34 - 14 = 20ème jour. Fécondation = 20ème jour. Le stade morula est atteint 4 jours après la fécondation : 20 + 4 = 24ème jour du cycle menstruel.",
    "_synthese": "Corrigé officiel de la Faculté de Médecine de Mostaganem : D. La durée de la phase post-ovulatoire (lutéale) est constante (14 jours). L'ovulation se calcule donc par : Durée du cycle - 14. (Chapitre : La 1ère semaine de développement embryonnaire).",
    "_remarque": "Astuce concours / EMD : Morula = Ovulation (Durée - 14) + 4 jours = (34 - 14) + 4 = 24ème jour."
  },
  "embryo-15": {
    "A": "Vrai (corrigé officiel). Chez l'espèce humaine et les mammifères, la segmentation de l'œuf est asynchrone (l'un des blastomères se divise avant l'autre, générant des stades intermédiaires à 3, 5, 7 cellules).",
    "B": "Faux (corrigé officiel). Elle se produit dès les premières heures suivant la fécondation, au cours de la première semaine.",
    "C": "Faux (corrigé officiel). Elle a lieu pendant la migration tubaire et précède l'arrivée dans la cavité utérine.",
    "D": "Faux (corrigé officiel). La proposition A est exacte.",
    "_synthese": "Corrigé officiel de la Faculté de Médecine de Mostaganem : A. Les trois caractéristiques de la segmentation humaine sont : totale, asynchrone et rotationnelle. (Chapitre : La 1ère semaine de développement embryonnaire).",
    "_remarque": "Astuce concours / EMD : Segmentation humaine = totale, asynchrone, rotationnelle, sans augmentation de volume."
  },
  "embryo-16": {
    "A": "Faux (corrigé officiel). La zone pellucide a été éliminée lors de l'éclosion préalablement au contact avec l'endomètre.",
    "B": "Vrai (corrigé officiel). Chez l'espèce humaine, le blastocyste s'oriente et aborde l'épithélium de l'endomètre par son pôle embryonnaire (pôle renfermant le bouton embryonnaire).",
    "C": "Faux (corrigé officiel). Le syncytiotrophoblaste commence à se former au moment de l'invasion, mais c'est par le pôle embryonnaire que se fait l'orientation et l'adhésion initiale.",
    "D": "Faux (corrigé officiel). La proposition B est exacte.",
    "_synthese": "Corrigé officiel de la Faculté de Médecine de Mostaganem : B. L'adhésion par le pôle embryonnaire assure que l'embryon s'enfouit face au lit vasculaire maternel optimal. (Chapitre : La 2ème semaine de développement embryonnaire).",
    "_remarque": "Astuce concours / EMD : Abord de l'endomètre = Pôle embryonnaire (chez l'homme)."
  },
  "embryo-17": {
    "A": "Vrai (corrigé officiel). Immédiatement avant la nidation, l'œuf subit l'éclosion : la zone pellucide se déchire et se résorbe sous l'effet d'enzymes protéolytiques pour exposer le trophoblaste à l'endomètre.",
    "B": "Faux (corrigé officiel). La maturation de l'ovocyte I en ovocyte II a lieu juste avant l'ovulation dans l'ovaire.",
    "C": "Faux (corrigé officiel). Le taux de progestérone doit au contraire être élevé pour maintenir l'endomètre réceptif (décidualisation).",
    "D": "Faux (corrigé officiel). La proposition A est exacte.",
    "_synthese": "Corrigé officiel de la Faculté de Médecine de Mostaganem : A. L'éclosion blastocytaire est la condition sine qua non de l'attachement à la muqueuse utérine. (Chapitre : La 1ère semaine de développement embryonnaire).",
    "_remarque": "Astuce concours / EMD : Immédiatement avant la nidation = éclosion (rupture/déchirure de la zone pellucide)."
  },
  "embryo-18": {
    "A": "Faux (corrigé officiel). La réplication de l'ADN s'effectue dans chacun des deux pronuclei (mâle et femelle) indépendamment.",
    "B": "Faux (corrigé officiel). Le fuseau mitotique s'organise à partir du centriole proximal apporté par le spermatozoïde.",
    "C": "Vrai (corrigé officiel). L'amphimixie correspond au rapprochement intime, à la mise côte à côte des pronuclei mâle et femelle, à l'effacement de leurs membranes nucléaires et à l'appariement des chromosomes homologues sur le fuseau mitotique.",
    "D": "Faux (corrigé officiel). La proposition C est exacte.",
    "_synthese": "Corrigé officiel de la Faculté de Médecine de Mostaganem : C. L'amphimixie concrétise la fin de la fécondation et le rétablissement de la diploïdie (2n chromosomes). (Chapitre : La fécondation).",
    "_remarque": "Astuce concours / EMD : Amphimixie = mise côte à côte des pronuclei et fusion des deux génomes parentaux."
  },
  "embryo-19": {
    "A": "Proposition fausse à cocher (corrigé officiel). Un nombre de spermatozoïdes inférieur à 40 millions par ml (ou < 15 millions/ml selon les normes actuelles de l'OMS) définit une oligospermie, qui est défavorable à la fécondation.",
    "B": "Proposition vraie (non retenue). Une glaire cervicale filante, claire et de bonne viscosité favorise la pénétration des spermatozoïdes.",
    "C": "Proposition vraie (non retenue). L'absence d'infection vaginale ou tubaire préserve la viabilité des gamètes.",
    "D": "Proposition vraie (non retenue). Un cycle ovulatoire de bonne qualité avec corps jaune fonctionnel est indispensable.",
    "_synthese": "Corrigé officiel de la Faculté de Médecine de Mostaganem : A. La fertilité requiert des paramètres spermatiques quantitatifs et qualitatifs adéquats (> 15-40 millions/ml). (Chapitre : La fécondation).",
    "_remarque": "Astuce concours / EMD : Oligospermie (< 40 millions/ml) = facteur défavorable / infertilité masculine."
  },
  "embryo-20": {
    "A": "Faux (corrigé officiel). Dans le canal déférent, les spermatozoïdes sont stockés et quiescents.",
    "B": "Faux (corrigé officiel). La prostate sécrète le liquide séminal mais ne capacite pas les spermatozoïdes.",
    "C": "Vrai (corrigé officiel). La capacitation est un processus physiologique obligatoire d'activation métabolique et membranaire qui se déroule au cours de l'ascension des spermatozoïdes dans les voies génitales féminines (utérus et trompes de Fallope).",
    "D": "Faux (corrigé officiel). La capacitation précède obligatoirement la réaction acrosomiale.",
    "_synthese": "Corrigé officiel de la Faculté de Médecine de Mostaganem : C. La capacitation élimine les glycoprotéines séminales et déstabilise la membrane pour permettre la réaction acrosomique ultérieure. (Chapitre : La fécondation).",
    "_remarque": "Astuce concours / EMD : Lieu de la capacitation = Voies génitales féminines."
  },
  "embryo-21": {
    "A": "Faux (corrigé officiel). La membrane de Heuser borde initialement la cavité du lécithocèle primaire (vésicule vitelline primitive).",
    "B": "Vrai (corrigé officiel). La membrane de Heuser (membrane exo-cœlomique) se forme vers le 9ème-10ème jour du développement embryonnaire à partir de la prolifération de cellules hypoblastiques.",
    "C": "Faux (corrigé officiel). Elle dérive de l'hypoblaste (endoblaste primitif), et non du mésenchyme intra-embryonnaire.",
    "D": "Faux (corrigé officiel). Elle ne donne pas naissance à l'ectoblaste.",
    "_synthese": "Corrigé officiel de la Faculté de Médecine de Mostaganem : B. La membrane de Heuser délimite le lécithocèle primaire au 9-10ème jour (S2). (Chapitre : La 2ème semaine de développement embryonnaire).",
    "_remarque": "Astuce concours / EMD : Membrane de Heuser = hypoblaste + 10ème jour + délimite le lécithocèle primaire."
  },
  "embryo-22": {
    "A": "Vrai (corrigé officiel). Le cytotrophoblaste s'individualise au début de la deuxième semaine (8ème jour) par individualisation d'une assise cellulaire mononucléée interne issue du trophoblaste.",
    "B": "Faux (corrigé officiel). C'est le syncytiotrophoblaste qui forme un magma multinucléé sans parois cellulaires.",
    "C": "Faux (corrigé officiel). C'est le syncytiotrophoblaste qui lyse et érode le stroma et les vaisseaux endométriaux.",
    "D": "Faux (corrigé officiel). La proposition A est exacte.",
    "_synthese": "Corrigé officiel de la Faculté de Médecine de Mostaganem : A. A J8, le trophoblaste se dédouble en cytotrophoblaste interne (cellules individualisées) et syncytiotrophoblaste externe. (Chapitre : La 2ème semaine de développement embryonnaire).",
    "_remarque": "Astuce concours / EMD : Cytotrophoblaste = interne, cellulaire, mononucléé, divisions mitotiques dès le début de S2."
  },
  "embryo-23": {
    "A": "Vrai (corrigé officiel). Le premier feuillet à s'individualiser à partir du bouton embryonnaire (au 7e-8e jour) est l'endoblaste (hypoblaste), suivi peu après de l'épiblaste (ectoblaste primaire).",
    "B": "Faux (corrigé officiel). L'ectoblaste s'individualise juste après l'hypoblaste.",
    "C": "Faux (corrigé officiel). Le mésoblaste est le troisième feuillet, formé au cours de la 3ème semaine lors de la gastrulation.",
    "D": "Faux (corrigé officiel). Le trophoblaste est un tissu annexe et non un feuillet embryonnaire.",
    "_synthese": "Corrigé officiel de la Faculté de Médecine de Mostaganem : A. A J7-J8, la masse cellulaire interne se clive d'abord en une couche cubique inférieure tournée vers le blastocèle : l'endoblaste (hypoblaste). (Chapitre : La 2ème semaine de développement embryonnaire).",
    "_remarque": "Astuce concours / EMD : 1er feuillet formé = Endoblaste (hypoblaste) à J7-J8."
  },
  "embryo-24": {
    "A": "Faux (corrigé officiel de l'épreuve). L'implantation a débuté à la fin de la 1ère semaine (J6) et s'achève au cours de la 2ème semaine.",
    "B": "Faux (corrigé officiel). La migration a lieu durant la première semaine.",
    "C": "Faux (corrigé officiel). La neurulation débute à la 3ème semaine et se poursuit à la 4ème semaine.",
    "D": "Vrai (corrigé officiel). Aucune des propositions n'est la réponse exclusive attendue par l'enseignant pour caractériser la 2ème semaine de manière spécifique.",
    "_synthese": "Corrigé officiel de la Faculté de Médecine de Mostaganem : D. La 2ème semaine est avant tout la semaine du 'disque embryonnaire didermique' et des annexes primitives. (Chapitre : La 2ème semaine de développement embryonnaire).",
    "_remarque": "Astuce concours / EMD : S2 = Didermique, formation de la cavité amniotique et du lécithocèle."
  },
  "embryo-25": {
    "A": "Faux (corrigé officiel). L'aspect de mûre caractérise la morula (3e-4e jour).",
    "B": "Faux (corrigé officiel). L'œuf arrive dans la cavité utérine vers le 5e-6e jour.",
    "C": "Vrai (corrigé officiel). A la fin du 10ème jour, le blastocyste est totalement enfoui au sein du stroma endométrial; la porte d'entrée est scellée par un bouchon de fibrine.",
    "D": "Faux (corrigé officiel). L'œuf a quitté l'ampoule tubaire depuis le début de la segmentation.",
    "_synthese": "Corrigé officiel de la Faculté de Médecine de Mostaganem : C. L'implantation complète interstitielle s'achève à J10 avec la cicatrisation de l'épithélium maternel. (Chapitre : La 2ème semaine de développement embryonnaire).",
    "_remarque": "Astuce concours / EMD : Fin du 10ème jour = Œuf totalement enfoui dans l'endomètre."
  },
  "embryo-26": {
    "A": "Faux (corrigé officiel). L'ectoblaste participe à la constitution de l'embryon et du plancher amniotique.",
    "B": "Vrai (corrigé officiel). Le pédicule embryonnaire (futur cordon ombilical) est une bande de mésenchyme extra-embryonnaire (magma réticulé) qui rattache le disque didermique au chorion.",
    "C": "Faux (corrigé officiel). Le trophoblaste forme la coque externe de l'œuf.",
    "D": "Faux (corrigé officiel). La proposition B est exacte.",
    "_synthese": "Corrigé officiel de la Faculté de Médecine de Mostaganem : B. Le cœlome extra-embryonnaire clive le mésenchyme en deux feuillets, sauf au niveau du pédicule embryonnaire qui persiste. (Chapitre : La 2ème semaine de développement embryonnaire).",
    "_remarque": "Astuce concours / EMD : Pédicule embryonnaire = Mésenchyme extra-embryonnaire reliant embryon au chorion."
  },
  "embryo-27": {
    "A": "Vrai (corrigé officiel). Le syncytiotrophoblaste apparaît au tout début de la deuxième semaine (8ème jour) par fusion des cellules cytotrophoblastiques au pôle d'invasion.",
    "B": "Faux (corrigé officiel). Il dérive du trophoblaste primitif et non du mésenchyme extra-embryonnaire.",
    "C": "Faux (corrigé officiel). Il érode l'endomètre (la muqueuse) mais s'arrête physiologiquement avant de détruire le myomètre utérin.",
    "D": "Faux (corrigé officiel). La proposition A est exacte.",
    "_synthese": "Corrigé officiel de la Faculté de Médecine de Mostaganem : A. La formation du syncytiotrophoblaste marque le début de la phase didermique et invasive de l'œuf. (Chapitre : La 2ème semaine de développement embryonnaire).",
    "_remarque": "Astuce concours / EMD : Syncytiotrophoblaste = différenciation à J8 (début S2)."
  },
  "embryo-28": {
    "A": "Proposition vraie (non retenue). Le syncytiotrophoblaste forme la couche la plus externe du chorion.",
    "B": "Proposition vraie (non retenue). Le mésenchyme extra-embryonnaire tapisse la face interne du trophoblaste pour former la lame choriale.",
    "C": "Proposition vraie (non retenue). Le cytotrophoblaste constitue la couche cellulaire intermédiaire du chorion.",
    "D": "Proposition fausse à cocher (corrigé officiel). Le mésenchyme intra-embryonnaire se forme lors de la gastrulation (3ème semaine) à l'intérieur du disque embryonnaire; il ne participe pas au chorion.",
    "_synthese": "Corrigé officiel de la Faculté de Médecine de Mostaganem : D. Le chorion est composé de 3 éléments strictement extra-embryonnaires : syncytiotrophoblaste + cytotrophoblaste + mésenchyme extra-embryonnaire. (Chapitre : Évolution définitive des annexes embryonnaires).",
    "_remarque": "Astuce concours / EMD : Chorion = Trophoblaste (cyto + syncytio) + Mésenchyme EXTRA-embryonnaire."
  },
  "embryo-29": {
    "A": "Faux (corrigé officiel). Il manque l'amnios et le mésenchyme dans cette description.",
    "B": "Faux (corrigé officiel). La plaque choriale est d'origine fœtale/embryonnaire, et non maternelle (la plaque basale contient le tissu maternel).",
    "C": "Vrai (corrigé officiel). La plaque choriale (lame choriale) du placenta est constituée de l'épithélium amniotique, du mésenchyme extra-embryonnaire, du cytotrophoblaste et du syncytiotrophoblaste.",
    "D": "Faux (corrigé officiel). Le cœlome extra-embryonnaire est une cavité qui a disparu par accolement de l'amnios au chorion.",
    "_synthese": "Corrigé officiel de la Faculté de Médecine de Mostaganem : C. La plaque choriale regarde la cavité amniotique et porte l'insertion du cordon ombilical et les vaisseaux fœtaux superficiels. (Chapitre : Évolution définitive des annexes embryonnaires).",
    "_remarque": "Astuce concours / EMD : Plaque choriale fœtale = Amnios + Mésenchyme extra-embryonnaire + Trophoblaste (cyto + syncytio)."
  },
  "embryo-30": {
    "A": "Faux (corrigé officiel). L'endoblaste est le premier feuillet à se former à J7-J8.",
    "B": "Faux (selon le corrigé de l'épreuve). Bien que l'épiblaste/ectoblaste apparaisse après l'endoblaste en S2, la question de l'enseignant évalue le feuillet intermédiaire de gastrulation.",
    "C": "Vrai (corrigé officiel). Le corrigé officiel retient C (Le mésoblaste comme deuxième grand événement feuilletaire de la gastrulation).",
    "D": "Faux (corrigé officiel). Le trophoblaste n'est pas un feuillet embryonnaire.",
    "_synthese": "Corrigé officiel de la Faculté de Médecine de Mostaganem : C. La gastrulation en 3ème semaine met en place le 3ème feuillet (mésoblaste) entre l'ectoblaste et l'endoblaste. (Chapitre : La 3ème semaine de développement embryonnaire).",
    "_remarque": "Astuce concours / EMD : Corrigé officiel de Mostaganem pour cette question : C (Le mésoblaste)."
  },
  "embryo-31": {
    "A": "Faux (corrigé officiel). L'ectoblaste ne possède aucune fonction endocrine chorionique.",
    "B": "Vrai (corrigé officiel). L'hCG (hormone gonadotrophine chorionique humaine) est synthétisée et sécrétée par le trophoblaste (spécifiquement le syncytiotrophoblaste) pour maintenir le corps jaune gravidique.",
    "C": "Faux (corrigé officiel). Le mésoblaste ne sécrète pas l'hCG.",
    "D": "Faux (corrigé officiel). L'endoblaste ne produit pas l'hCG.",
    "_synthese": "Corrigé officiel de la Faculté de Médecine de Mostaganem : B. L'hCG trophoblastique stimule la sécrétion continue de progestérone par le corps jaune pendant le premier trimestre. (Chapitre : La 2ème semaine de développement embryonnaire).",
    "_remarque": "Astuce concours / EMD : HCG = sécrétée par le trophoblaste (syncytiotrophoblaste)."
  },
  "embryo-32": {
    "A": "Faux (selon la clé officielle).",
    "B": "Vrai (corrigé officiel). Le corrigé officiel valide l'item B pour cette question.",
    "C": "Faux (corrigé officiel). Elle dérive de l'hypoblaste.",
    "D": "Faux (corrigé officiel).",
    "_synthese": "Corrigé officiel de la Faculté de Médecine de Mostaganem : B. La membrane de Heuser (membrane exo-cœlomique) borde la cavité vitelline primitive lors de la deuxième semaine. (Chapitre : La 2ème semaine de développement embryonnaire).",
    "_remarque": "Astuce concours / EMD : Corrigé officiel de l'épreuve : B."
  },
  "embryo-33": {
    "A": "Proposition vraie (non retenue). Le lécithocèle secondaire se forme au 13ème jour par étranglement du lécithocèle primaire.",
    "B": "Proposition vraie (non retenue). L'ectoblaste (épiblaste) s'individualise au 8ème jour.",
    "C": "Proposition fausse à cocher (corrigé officiel). Le nœud de Hensen se forme au cours de la 3ème semaine (J16) au sommet crânial de la ligne primitive lors de la gastrulation.",
    "D": "Proposition vraie (non retenue). La membrane de Heuser se forme au 9e-10e jour (2ème semaine).",
    "_synthese": "Corrigé officiel de la Faculté de Médecine de Mostaganem : C. Le nœud de Hensen est le centre organisateur majeur de la gastrulation qui s'édifie au cours de la troisième semaine. (Chapitre : La 2ème semaine de développement embryonnaire).",
    "_remarque": "Astuce concours / EMD : Nœud de Hensen = 3ème semaine (gastrulation). Absent en S2."
  },
  "embryo-34": {
    "A": "Faux (corrigé officiel). Il apparaît au 8ème jour (début de la deuxième semaine).",
    "B": "Vrai (corrigé officiel). Le syncytiotrophoblaste est un syncytium résultant de la fusion cellulaire, constitué d'un cytoplasme continu rempli d'un magma de noyaux sans membranes plasmiques séparatrices.",
    "C": "Faux (corrigé officiel). Il lyse l'endomètre mais respecte le myomètre.",
    "D": "Faux (corrigé officiel). La proposition B est exacte.",
    "_synthese": "Corrigé officiel de la Faculté de Médecine de Mostaganem : B. Le syncytiotrophoblaste est une masse cytoplasmique multinucléée hautement invasive. (Chapitre : La 2ème semaine de développement embryonnaire).",
    "_remarque": "Astuce concours / EMD : Syncytiotrophoblaste = magma de noyaux sans limites cellulaires (syncytium)."
  },
  "embryo-35": {
    "A": "Faux (corrigé officiel). Le mésoblaste para-axial s'organise en somites (sclérotome, myotome, dermatome).",
    "B": "Vrai (corrigé officiel). Les néphrotomes (cordons néphrogènes à l'origine du pronephros, mésonéphros et métanéphros) s'individualisent au niveau du mésoblaste intermédiaire (pièces intermédiaires).",
    "C": "Faux (corrigé officiel). Le mésoblaste latéral se clive en somatopleure et splanchnopleure.",
    "D": "Faux (corrigé officiel). La proposition B est exacte.",
    "_synthese": "Corrigé officiel de la Faculté de Médecine de Mostaganem : B. Le mésoblaste intermédiaire est le précurseur exclusif de l'appareil urinaire et d'une partie de l'appareil génital. (Chapitre : La 3ème semaine de développement embryonnaire).",
    "_remarque": "Astuce concours / EMD : Néphrotomes = Mésoblaste intermédiaire."
  },
  "embryo-36": {
    "A": "Vrai (corrigé officiel). Les somites proviennent de la segmentation métamérique du mésoblaste para-axial de part et d'autre de la notochorde.",
    "B": "Faux (corrigé officiel). Le mésenchyme splanchnopleural tapisse l'intestin primitif.",
    "C": "Faux (corrigé officiel). Le mésoblaste intermédiaire donne les néphrotomes.",
    "D": "Faux (corrigé officiel). La proposition A est exacte.",
    "_synthese": "Corrigé officiel de la Faculté de Médecine de Mostaganem : A. Les 42 à 44 paires de somites se forment par clivage crânio-caudal du mésoblaste para-axial. (Chapitre : La 3ème semaine de développement embryonnaire).",
    "_remarque": "Astuce concours / EMD : Somites = Mésoblaste para-axial."
  },
  "embryo-37": {
    "A": "Proposition fausse à cocher (corrigé officiel). Il n'existe pas de stade de « cavité chordale ». La chorde se développe successivement par : processus chordal, canal chordal, plaque chordale, puis tige chordale pleine (notochorde).",
    "B": "Proposition vraie (non retenue). La plaque chordale s'intègre transitoirement au toit du lécithocèle.",
    "C": "Proposition vraie (non retenue). Le canal chordal correspond au creusement de la lumière dans le processus chordal.",
    "D": "Proposition vraie (non retenue). Le processus chordal est le prolongement initial tubulaire issu du nœud de Hensen.",
    "_synthese": "Corrigé officiel de la Faculté de Médecine de Mostaganem : A. La chorde dorsale sert d'inducteur primaire pour la formation du tube neural sous-jacent. (Chapitre : La 3ème semaine de développement embryonnaire).",
    "_remarque": "Astuce concours / EMD : Étapes de la chorde : Processus -> Canal -> Plaque -> Cordon plein. Pas de cavité chordale."
  },
  "embryo-38": {
    "A": "Faux (corrigé officiel). La ligne primitive apparaît au 15ème jour (début de la 3ème semaine).",
    "B": "Vrai (corrigé officiel). L'apparition de la ligne primitive permet la délamination et l'invagination des cellules de l'épiblaste (ectoblaste) qui migrent pour constituer le mésoblaste intra-embryonnaire et remplacer l'hypoblaste par l'endoblaste.",
    "C": "Faux (corrigé officiel). L'endoblaste embryonnaire primitif (hypoblaste) préexistait déjà dès le 7ème jour.",
    "D": "Faux (corrigé officiel). La proposition B est exacte.",
    "_synthese": "Corrigé officiel de la Faculté de Médecine de Mostaganem : B. La ligne primitive est le foyer d'invagination épithélio-mésenchymateuse de la gastrulation. (Chapitre : La 3ème semaine de développement embryonnaire).",
    "_remarque": "Astuce concours / EMD : Ligne primitive = permet l'invagination des cellules épiblastiques (S3)."
  },
  "embryo-39": {
    "A": "Proposition vraie (non retenue). Le placenta humain est hémochorial (le sang maternel baigne directement les villosités choriales).",
    "B": "Proposition fausse à cocher (corrigé officiel). Le placenta humain n'est PAS diffus; il est discoïde (localisé en galette circulaire sur une zone restreinte de l'endomètre).",
    "C": "Proposition vraie (non retenue). Il est chorio-allantoïdien par la vascularisation issue des vaisseaux allantoïdiens du cordon ombilical.",
    "D": "Proposition vraie (non retenue). Sa forme macroscopique est un disque (discoïde).",
    "_synthese": "Corrigé officiel de la Faculté de Médecine de Mostaganem : B. Le placenta diffus s'observe chez la truie et la jument, jamais chez la femme. (Chapitre : Évolution définitive des annexes embryonnaires).",
    "_remarque": "Astuce concours / EMD : Placenta humain = Hémochorial, Discoïde, Décidual, Chorio-allantoïdien. Il n'est PAS diffus."
  },
  "embryo-40": {
    "A": "Faux (corrigé officiel). Le lécithocèle secondaire apparaît à la fin de la 2ème semaine (J13).",
    "B": "Faux (corrigé officiel). L'ectoblaste apparaît au 8ème jour (2ème semaine).",
    "C": "Vrai (corrigé officiel). La gouttière neurale se forme à la fin de la troisième semaine (J18-J19) par invagination de la plaque neurale au-dessus de la chorde dorsale.",
    "D": "Faux (corrigé officiel). L'endoblaste primitif apparaît en 2ème semaine.",
    "_synthese": "Corrigé officiel de la Faculté de Médecine de Mostaganem : C. La neurulation débute en fin de 3ème semaine avec l'induction de la plaque neurale puis son creusement en gouttière neurale. (Chapitre : La 3ème semaine de développement embryonnaire).",
    "_remarque": "Astuce concours / EMD : Gouttière neurale = fin de 3ème semaine."
  },
  "embryo-41": {
    "A": "Faux (corrigé officiel). Il apparaît au tout début de la 3ème semaine (vers J15-J16).",
    "B": "Faux (corrigé officiel). Il marque le début et le centre organisateur de la gastrulation, non sa fin.",
    "C": "Vrai (corrigé officiel). Le nœud de Hensen forme un renflement cellulaire circulaire marquant l'arrêt antérieur (céphalique) de la ligne primitive.",
    "D": "Faux (corrigé officiel). La proposition C est exacte.",
    "_synthese": "Corrigé officiel de la Faculté de Médecine de Mostaganem : C. Le nœud de Hensen est l'équivalent chez les mammifères de la lèvre dorsale du blastopore de Spemann. (Chapitre : La 3ème semaine de développement embryonnaire).",
    "_remarque": "Astuce concours / EMD : Nœud de Hensen = extrémité céphalique marquant l'arrêt de la ligne primitive."
  },
  "embryo-42": {
    "A": "Proposition vraie (non retenue). Hémochorial = les villosités baignent dans les lacunes de sang maternel.",
    "B": "Proposition fausse à cocher (corrigé officiel). Le placenta humain n'est pas diffus mais strictement discoïde.",
    "C": "Proposition vraie (non retenue). Décidual = lors de la délivrance, la caduque basale maternelle s'élimine avec le placenta.",
    "D": "Proposition vraie (non retenue). Pseudo-cotylédoné = divisé sur sa face maternelle en cotylédons par les septa intercotylédonaires.",
    "_synthese": "Corrigé officiel de la Faculté de Médecine de Mostaganem : B. Caractéristiques du placenta humain : Hémochorial, Discoïde, Décidual, Pseudo-cotylédoné. (Chapitre : Évolution définitive des annexes embryonnaires).",
    "_remarque": "Astuce concours / EMD : Le placenta humain n'est JAMAIS diffus."
  },
  "embryo-43": {
    "A": "Faux (corrigé officiel). Le disque didermique est l'aboutissement de la 2ème semaine.",
    "B": "Faux (corrigé officiel). Le trophoblaste s'établit dès la première et la deuxième semaine.",
    "C": "Vrai (corrigé officiel). La troisième semaine aboutit à l'apparition des villosités placentaires tertiaires, définies par l'apparition de vaisseaux capillaires fœtaux fonctionnels au sein de leur axe mésenchymateux (vers J21).",
    "D": "Faux (corrigé officiel). La proposition C est exacte.",
    "_synthese": "Corrigé officiel de la Faculté de Médecine de Mostaganem : C. Villosités I = cyto + syncytio. Villosités II = + mésenchyme. Villosités III = + capillaires sanguins fœtaux (J21). (Chapitre : La 3ème semaine de développement embryonnaire).",
    "_remarque": "Astuce concours / EMD : Fin S3 = Villosités choriales tertiaires vascularisées."
  },
  "embryo-44": {
    "A": "Faux (corrigé officiel). Il fait suite au stade de processus chordal qui se creuse.",
    "B": "Faux (corrigé officiel). Il précède la formation de la plaque chordale.",
    "C": "Faux (corrigé officiel). Il fait communiquer la cavité amniotique avec le lécithocèle (canal neurentérique), et non avec le cœlome externe.",
    "D": "Vrai (corrigé officiel). Aucune des propositions A, B, C n'est correcte.",
    "_synthese": "Corrigé officiel de la Faculté de Médecine de Mostaganem : D. Le canal chordal résulte du creusement du processus chordal et s'ouvre transitoirement par le canal neurentérique. (Chapitre : La 3ème semaine de développement embryonnaire).",
    "_remarque": "Astuce concours / EMD : Canal chordal = relie cavité amniotique et lécithocèle (canal de Lieberkühn / neurentérique)."
  },
  "embryo-45": {
    "A": "Faux (corrigé officiel). Les villosités secondaires sont avasculaires; ce sont les tertiaires qui sont vascularisées.",
    "B": "Faux (corrigé officiel). Elles possèdent un axe de mésenchyme extra-embryonnaire.",
    "C": "Faux (corrigé officiel). Elles se développent sur toute la périphérie de la sphère choriale.",
    "D": "Vrai (corrigé officiel). Les villosités secondaires sont constituées par un axe de mésenchyme extra-embryonnaire revêtu par une assise de cytotrophoblaste et recouvert extérieurement de syncytiotrophoblaste.",
    "_synthese": "Corrigé officiel de la Faculté de Médecine de Mostaganem : D. La villosité secondaire est constituée des 3 composantes du chorion : mésenchyme + cyto + syncytiotrophoblaste. (Chapitre : Évolution définitive des annexes embryonnaires).",
    "_remarque": "Astuce concours / EMD : Villosité secondaire = Syncytiotrophoblaste + Cytotrophoblaste + Axe mésenchymateux sans vaisseaux."
  },
  "embryo-46": {
    "A": "Faux (corrigé officiel). Le mésoderme donne les muscles, les os, le système cardiovasculaire et le système urogénital.",
    "B": "Faux (corrigé officiel). L'endoderme donne le revêtement épithélial du tube digestif et des voies respiratoires.",
    "C": "Faux (corrigé officiel). L'épiblaste s'est différencié au cours de la gastrulation en ectoderme, mésoderme et endoderme.",
    "D": "Vrai (corrigé officiel). Le tube neural dérive de l'ectoderme (spécifiquement le neuroectoderme induit par la chorde dorsale).",
    "_synthese": "Corrigé officiel de la Faculté de Médecine de Mostaganem : D. Le neuroectoderme donne naissance au tube neural (SNC, rétine) et aux crêtes neurales (SNP, mélanocytes). (Chapitre : La 3ème semaine de développement embryonnaire).",
    "_remarque": "Astuce concours / EMD : Tube neural = dérivé de l'ectoderme (neuroectoderme)."
  },
  "embryo-47": {
    "A": "Faux (corrigé officiel). L'axe médio-latéral est perpendiculaire à la ligne primitive.",
    "B": "Vrai (corrigé officiel). La ligne primitive apparaît dans la région caudale de l'épiblaste et s'étend en direction céphalique, définissant l'axe cranio-caudal (longitudinal) de l'embryon.",
    "C": "Faux (corrigé officiel). L'axe ventro-dorsal est l'axe dorso-ventral de polarité des feuillets.",
    "D": "Faux (corrigé officiel).",
    "_synthese": "Corrigé officiel de la Faculté de Médecine de Mostaganem : B. La ligne primitive établit formellement la symétrie bilatérale et les axes céphalo-caudal et médio-latéral. (Chapitre : La 3ème semaine de développement embryonnaire).",
    "_remarque": "Astuce concours / EMD : Orientation de la ligne primitive = Axe Cranio-caudal."
  },
  "embryo-48": {
    "A": "Faux (corrigé officiel). Le pédicule embryonnaire loge l'allantoïde mais ne lui donne pas naissance.",
    "B": "Faux (corrigé officiel). Le mésenchyme est le tissu de soutien.",
    "C": "Vrai (corrigé officiel). L'allantoïde est un diverticule endoblastique digitiforme qui bourgeonne à partir de la partie postéro-caudale du lécithocèle secondaire (vésicule vitelline) vers le 16ème jour.",
    "D": "Faux (corrigé officiel).",
    "_synthese": "Corrigé officiel de la Faculté de Médecine de Mostaganem : C. L'allantoïde s'insinue dans le pédicule embryonnaire et ses vaisseaux formeront les artères et la veine ombilicales. (Chapitre : Évolution définitive des annexes embryonnaires).",
    "_remarque": "Astuce concours / EMD : Allantoïde = diverticule du lécithocèle secondaire (endoblaste)."
  },
  "embryo-49": {
    "A": "Faux (corrigé officiel).",
    "B": "Faux (corrigé officiel). La notochorde est une tige mésodermique axiale inductrice.",
    "C": "Vrai (corrigé officiel). Les cellules germinales primordiales (gonocytes primordiaux) s'individualisent dans la paroi endoblastique postérieure du lécithocèle secondaire à proximité de l'allantoïde vers la 3ème semaine.",
    "D": "Faux (corrigé officiel).",
    "_synthese": "Corrigé officiel de la Faculté de Médecine de Mostaganem : C. Les gonocytes primordiaux migreront ensuite activement le long du mésentère dorsal pour coloniser les crêtes génitales en 5ème semaine. (Chapitre : La 3ème semaine de développement embryonnaire).",
    "_remarque": "Astuce concours / EMD : Origine des gonocytes primordiaux = Endoblaste du lécithocèle secondaire."
  },
  "embryo-50": {
    "A": "Faux (corrigé officiel). L'anencéphalie résulte d'un défaut de fermeture du neuropore antérieur.",
    "B": "Vrai (corrigé officiel). L'apparition de deux lignes primitives ou la duplication du nœud de Hensen conduit au développement de deux axes embryonnaires conjoints incomplètement séparés, aboutissant à des monstres doubles (jumeaux siamois).",
    "C": "Faux (corrigé officiel). L'hydrocéphalie résulte d'une sténose de l'aqueduc de Sylvius ou d'un trouble de résorption du LCS.",
    "D": "Faux (corrigé officiel). Le spina bifida résulte d'un défaut de fermeture du neuropore postérieur.",
    "_synthese": "Corrigé officiel de la Faculté de Médecine de Mostaganem : B. La duplication de la ligne primitive est la base embryologique des jumeaux soudés monozygotes imparfaits. (Chapitre : La Grossesse gémellaire).",
    "_remarque": "Astuce concours / EMD : Deux lignes primitives = Monstre double (jumeaux siamois)."
  },
  "embryo-51": {
    "A": "Vrai (corrigé officiel). Durant la 3ème semaine, la zone cardiogène (croissant cardiogénique) est située en avant (en position crâniale) par rapport à la membrane pharyngienne; la bascule crânio-caudale lors de la délimitation la ramènera en position thoracique ventrale.",
    "B": "Faux (corrigé officiel). La membrane cloacale est caudale.",
    "C": "Faux (corrigé officiel). Le nœud de Hensen est plus caudal.",
    "D": "Faux (corrigé officiel). La proposition A est exacte.",
    "_synthese": "Corrigé officiel de la Faculté de Médecine de Mostaganem : A. L'aire cardiogène se situe primitivement en avant de l'aire cérébrale avant d'être rabattue dans la cavité thoracique par la plicature céphalique. (Chapitre : La 3ème semaine de développement embryonnaire).",
    "_remarque": "Astuce concours / EMD : Zone cardiogène = En avant de la membrane pharyngienne en S3."
  },
  "embryo-52": {
    "A": "Proposition fausse à cocher (corrigé officiel). La formation de la plaque neurale a lieu à la fin de la 3ème semaine lors de la neurulation, avant la délimitation qui est le processus morphogénétique majeur de la 4ème semaine.",
    "B": "Proposition vraie (non retenue). La délimitation ferme l'embryon sur sa face ventrale.",
    "C": "Proposition vraie (non retenue). La plicature transversale et longitudinale étrangle le lécithocèle pour former l'intestin primitif intra-embryonnaire.",
    "D": "Proposition vraie (non retenue). Le regroupement du pédicule de fixation, du canal vitellin et de l'amnios forme le cordon ombilical primitif.",
    "_synthese": "Corrigé officiel de la Faculté de Médecine de Mostaganem : A. La délimitation transforme le disque embryonnaire plat tridermique en un embryon tubulaire tridimensionnel fermé. (Chapitre : La 4ème semaine de développement embryonnaire).",
    "_remarque": "Astuce concours / EMD : Plaque neurale = 3ème semaine. Délimitation = 4ème semaine."
  },
  "embryo-53": {
    "A": "Vrai (corrigé officiel). Les cellules des crêtes neurales sont des cellules d'origine ectoblastique douées d'une capacité migratoire extraordinaire, colonisant de nombreuses régions embryonnaires.",
    "B": "Faux (corrigé officiel). Elles dérivent des berges neuroectoblastiques de la gouttière neurale.",
    "C": "Faux (corrigé officiel). Les muscles squelettiques dérivent des myotomes des somites mésoblastiques.",
    "D": "Faux (corrigé officiel). La proposition A est exacte.",
    "_synthese": "Corrigé officiel de la Faculté de Médecine de Mostaganem : A. Les cellules des crêtes neurales sont souvent appelées le 'quatrième feuillet' tant leurs dérivés sont ubiquitaires (ganglions sensitifs, système sympathique, mélanocytes, médullosurrénale, massif facial). (Chapitre : La 4ème semaine de développement embryonnaire).",
    "_remarque": "Astuce concours / EMD : Crêtes neurales = cellules neuroectodermiques à haute capacité migratoire."
  },
  "embryo-54": {
    "A": "Faux (corrigé officiel). Les os dérivent du sclérotome (somites mésoblastiques para-axiaux) et de la somatopleure.",
    "B": "Vrai (corrigé officiel). Le mésoblaste intermédiaire forme les cordons néphrogènes donnant naissance au système urinaire (reins et uretères) et génital.",
    "C": "Faux (corrigé officiel). Les muscles dérivent des myotomes somoblastiques et de la splanchnopleure.",
    "D": "Faux (corrigé officiel). La proposition B est exacte.",
    "_synthese": "Corrigé officiel de la Faculté de Médecine de Mostaganem : B. Le rein provient de l'évolution du mésoblaste intermédiaire (blastème métanéphrogène). (Chapitre : Évolution définitive des feuillets embryonnaires).",
    "_remarque": "Astuce concours / EMD : Mésoblaste intermédiaire = Reins et voies urinaires."
  },
  "embryo-55": {
    "A": "Vrai (corrigé officiel). La délimitation de l'embryon (plicatures crânio-caudale et transversale sous l'effet de l'expansion de la cavité amniotique) est l'événement caractéristique majeur de la quatrième semaine.",
    "B": "Faux (corrigé officiel). La segmentation s'achève à la première semaine.",
    "C": "Faux (corrigé officiel). La gastrulation se produit au cours de la troisième semaine.",
    "D": "Faux (corrigé officiel). La fixation à l'endomètre a lieu à J6 (S1).",
    "_synthese": "Corrigé officiel de la Faculté de Médecine de Mostaganem : A. S4 = Délimitation (l'embryon s'enroule, se ferme et acquiert sa forme cylindrique caractéristique). (Chapitre : La 4ème semaine de développement embryonnaire).",
    "_remarque": "Astuce concours / EMD : 4ème semaine = Délimitation de l'embryon."
  },
  "embryo-56": {
    "A": "Proposition fausse à cocher (corrigé officiel). La médullosurrénale ne dérive pas du mésoblaste; elle dérive des crêtes neurales (neuroectoderme). C'est la corticosurrénale qui dérive du mésoblaste cœlomique.",
    "B": "Proposition vraie (non retenue). Le système cardiovasculaire dérive du mésoblaste.",
    "C": "Proposition vraie (non retenue). La rate dérive du mésenchyme mésoblastique du mésogastre dorsal.",
    "D": "Proposition vraie (non retenue). Les reins dérivent du mésoblaste intermédiaire.",
    "_synthese": "Corrigé officiel de la Faculté de Médecine de Mostaganem : A. La médullo-surrénale est un ganglion sympathique modifié issu des crêtes neurales. (Chapitre : Évolution définitive des feuillets embryonnaires).",
    "_remarque": "Astuce concours / EMD : Médullo-surrénale = Crêtes neurales (ectoderme). Corticosurrénale = Mésoblaste."
  },
  "embryo-57": {
    "A": "Proposition fausse à cocher (corrigé officiel). Le système nerveux central dérive de l'ectoderme (tube neural), et non de l'endoblaste.",
    "B": "Proposition vraie (non retenue). Le revêtement épithélial du tube digestif dérive de l'endoblaste.",
    "C": "Proposition vraie (non retenue). Le parenchyme hépatique dérive du diverticule hépatique endoblastique.",
    "D": "Proposition vraie (non retenue). L'épithélium thyroïdien dérive de l'endoblaste du plancher pharyngien.",
    "_synthese": "Corrigé officiel de la Faculté de Médecine de Mostaganem : A. L'endoblaste forme le revêtement de l'arbre respiratoire, du tractus digestif et de leurs glandes annexes. (Chapitre : Évolution définitive des feuillets embryonnaires).",
    "_remarque": "Astuce concours / EMD : SNC = Ectoderme. Tube digestif, foie, thyroïde = Endoblaste."
  },
  "embryo-58": {
    "A": "Faux (corrigé officiel). L'ectoblaste forme la peau et le système nerveux.",
    "B": "Faux (corrigé officiel). L'endoblaste forme l'appareil digestif et respiratoire.",
    "C": "Vrai (corrigé officiel). Les reins proviennent du mésoblaste (mésoblaste intermédiaire ou cordons néphrogènes).",
    "D": "Faux (corrigé officiel). Le trophoblaste forme les tissus placentaires.",
    "_synthese": "Corrigé officiel de la Faculté de Médecine de Mostaganem : C. Le pronephros, le mésonéphros et le métanéphros (rein définitif) dérivent tous du mésoblaste intermédiaire. (Chapitre : Évolution définitive des feuillets embryonnaires).",
    "_remarque": "Astuce concours / EMD : Reins = Mésoblaste (intermédiaire)."
  },
  "embryo-59": {
    "A": "Vrai (corrigé officiel). Le cordon ombilical se constitue au cours de la quatrième semaine lorsque la délimitation rabat le pédicule embryonnaire et le canal vitellin vers la région ombilicale ventrale.",
    "B": "Faux (corrigé officiel). Le cordon ombilical est recouvert extérieurement par l'amnios, mais sa constitution est définie en S4.",
    "C": "Faux (corrigé officiel). C'est le canal vitellin qui relie la vésicule ombilicale à l'intestin.",
    "D": "Faux (corrigé officiel).",
    "_synthese": "Corrigé officiel de la Faculté de Médecine de Mostaganem : A. Le cordon ombilical mature contient la gelée de Wharton, 2 artères ombilicales et 1 veine ombilicale. (Chapitre : Évolution définitive des annexes embryonnaires).",
    "_remarque": "Astuce concours / EMD : Constitution du cordon ombilical = 4ème semaine (délimitation)."
  },
  "embryo-60": {
    "A": "Faux (corrigé officiel). Le lécithocèle secondaire s'est formé à la fin de la 2ème semaine.",
    "B": "Vrai (corrigé officiel). Lors de la délimitation de l'embryon (plicatures crânio-caudale et latérales en S4), la partie supérieure du lécithocèle secondaire est pincée et intégrée dans le corps de l'embryon pour constituer l'intestin primitif.",
    "C": "Faux (corrigé officiel). La gouttière neurale s'est formée à la fin de la 3ème semaine.",
    "D": "Faux (corrigé officiel). Le cœlome externe s'est formé en 2ème semaine.",
    "_synthese": "Corrigé officiel de la Faculté de Médecine de Mostaganem : B. L'intestin primitif se divise en intestin antérieur, moyen (ouvert sur le canal vitellin) et postérieur. (Chapitre : La 4ème semaine de développement embryonnaire).",
    "_remarque": "Astuce concours / EMD : Délimitation embryonnaire (S4) -> formation de l'intestin primitif."
  }
};
